function panel(scene, mood, say, cap, key, layout, bubble) {
  var f = P[scene]; if (!f) return '';
  var k = String(key || '0').replace(/[^a-z0-9]/gi, '');
  // layout: left (ค่าเดิม) | right (น้องม้วนขวา หันซ้าย) | center (น้องม้วนกลาง) · bubble: talk (ค่าเดิม) | think | shout | caption
  var L = /^(right|center)$/.test(layout || '') ? layout : 'left', B = /^(think|shout|caption)$/.test(bubble || '') ? bubble : 'talk';
  return '<figure class="gd-cm l-' + L + ' b-' + B + '" aria-hidden="true"><svg class="gd-cm-bg" viewBox="0 0 360 180" preserveAspectRatio="xMidYMax slice">' + f(k) + '</svg>' +
    '<span class="gd-cm-m">' + (window.VCMascot ? window.VCMascot.svg(mood, 92) : '') + '</span>' +
    (say ? '<figcaption class="gd-cm-bub">' + say + '</figcaption>' : '') + (cap ? '<span class="gd-cm-cap">' + cap + '</span>' : '') + '</figure>';
}

